const D = { density: .55, energy: .6, speed: 1, scale: 1, harmon: 1, hue: 210, x: .5, y: .5, style: 'spectral', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const gridN = Math.max(4, Math.min(11, Math.round(4 + P.density * 7)));
const cells = gridN * gridN;

// coarse-ish full buffer so alpha compositing + its own HSB colormode are clean
if (!S.g || S.gkey !== width + 'x' + height) {
  S.g = createGraphics(width, height); S.g.pixelDensity(1);
  S.g.colorMode(HSB, 360, 100, 100, 100);
  S.gkey = width + 'x' + height;
}
const g = S.g;

// seed-dependent per-cell caches (rebuild on seed or grid change)
if (S.seedUsed !== P.seed || S.gN !== gridN) {
  S.seedUsed = P.seed; S.gN = gridN;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.pOff = new Float32Array(cells); S.dMul = new Float32Array(cells);
  S.hJit = new Float32Array(cells); S.lit = new Float32Array(cells);
  for (let c = 0; c < cells; c++) {
    S.pOff[c] = fr(c + 1) * TAU;
    S.dMul[c] = 0.65 + fr(c + 101) * 0.7;
    S.hJit[c] = (fr(c + 201) - 0.5) * 26;
    S.lit[c] = 0.72 + fr(c + 301) * 0.28;
  }
}

const style = P.style;
const hMul = P.harmon;
const drift = K.t * 0.06 * (0.4 + P.speed * 0.9);          // continuous phase precession (never re-phases)
const colorDrift = (K.t * 5) % 360;                        // slow spectral rotation (motion floor, speed-independent)
const wave = 0.16 * Math.sin(K.t * 0.045 + K.section * 0.7) + 0.10 + (P.x - 0.5) * 0.15; // traveling morph across the wall
const expo = 0.5 + P.energy * 0.95 + K.intensity * 0.22 + A.rms * 0.55 + A.bass * 0.5 + K.pulse * 0.28;
const swell = 0.85 + (K.swell || 0) * 0.3 + A.lowmid * 0.4 + (P.y - 0.5) * 0.1;

const cw = width / gridN, ch = height / gridN;
const fillf = 0.86 * P.scale;
const u = Math.min(width, height);

// ground tone per style (keeps luminance off the black floor)
let gH, gS, gV;
if (style === 'phosphor') { gH = 132; gS = 70; gV = 9; }
else if (style === 'amber') { gH = 32; gS = 78; gV = 9; }
else if (style === 'blueprint') { gH = 212; gS = 82; gV = 30; }
else if (style === 'neon') { gH = (P.hue + 300) % 360; gS = 62; gV = 10; }
else { gH = (P.hue + 20) % 360; gS = 52; gV = 15; }
g.background(gH, gS, gV);

// graticule for CRT / schematic looks
if (style === 'phosphor' || style === 'amber' || style === 'blueprint') {
  g.push();
  const glV = style === 'blueprint' ? 55 : 26;
  const glH = style === 'amber' ? 34 : (style === 'blueprint' ? 205 : 130);
  const glS = style === 'blueprint' ? 40 : 60;
  g.stroke(glH, glS, glV, style === 'blueprint' ? 32 : 15); g.strokeWeight(1);
  for (let i = 0; i <= gridN; i++) { g.line(i * cw, 0, i * cw, height); g.line(0, i * ch, width, i * ch); }
  g.pop();
}

function fig(cx, cy, ax, ay, mm, nn, ph, samples) {
  g.beginShape();
  for (let k = 0; k <= samples; k++) {
    const tt = k / samples * TAU;
    g.vertex(cx + ax * Math.sin(mm * tt + ph), cy + ay * Math.sin(nn * tt));
  }
  g.endShape();
}

g.push();
g.noFill();
const useAdd = style !== 'blueprint';
if (useAdd) g.blendMode(ADD);
const doMid = cells <= 81;
const coreW = Math.max(1, u * 0.0016 * P.scale);
for (let row = 0; row < gridN; row++) {
  for (let col = 0; col < gridN; col++) {
    const c = row * gridN + col;
    const m = (1 + col) * hMul, n = (1 + row) * hMul;
    const maxf = Math.max(m, n);
    let samples = Math.round(22 + 13 * maxf);
    if (samples > 150) samples = 150;
    const budget = Math.floor(7500 / cells);
    if (budget >= 30 && samples > budget) samples = budget;
    if (samples < 36) samples = 36;
    const cx = col * cw + cw * 0.5, cy = row * ch + ch * 0.5;
    const ax = cw * 0.5 * fillf * swell, ay = ch * 0.5 * fillf * swell;
    const ph = drift * S.dMul[c] + S.pOff[c] + wave * (col + row);
    const lit = S.lit[c];

    let hh, ss;
    if (style === 'phosphor') { hh = 128 + S.hJit[c] * 0.3; ss = 90; }
    else if (style === 'amber') { hh = 36 + S.hJit[c] * 0.25; ss = 92; }
    else if (style === 'blueprint') { hh = 200; ss = 12; }
    else if (style === 'neon') { hh = (P.hue + (col - row) * 16 + S.hJit[c] + colorDrift * 0.4) % 360; ss = 96; }
    else { hh = (P.hue + (col + row) / (2 * (gridN - 1)) * 285 + colorDrift + S.hJit[c]) % 360; ss = 88; }
    if (hh < 0) hh += 360;

    if (style === 'blueprint') {
      g.stroke(198, 22, 96, 62 + lit * 24); g.strokeWeight(Math.max(1, u * 0.0015 * P.scale));
      fig(cx, cy, ax, ay, m, n, ph, samples);
    } else {
      const halo = (14 + expo * 22) * lit;
      // soft halo
      g.stroke(hh, ss - 18, 100, Math.min(46, halo * 0.6));
      g.strokeWeight(Math.max(2, ch * 0.11 * (0.35 + P.energy)));
      fig(cx, cy, ax, ay, m, n, ph, samples);
      // mid body (skip on very dense grids for perf)
      if (doMid) {
        g.stroke(hh, ss - 6, 100, Math.min(60, halo));
        g.strokeWeight(Math.max(1.4, ch * 0.045 * (0.4 + P.energy * 0.8)));
        fig(cx, cy, ax, ay, m, n, ph, samples);
      }
      // bright core
      g.stroke((hh + 4) % 360, ss - 30, 100, 62 + P.energy * 28 + K.pulse * 20);
      g.strokeWeight(coreW);
      fig(cx, cy, ax, ay, m, n, ph, samples);
    }
  }
}
g.blendMode(BLEND);
g.pop();

// audio treble shimmer (partial, additive, never full-frame flash)
if (A.treble > 0.02 && style !== 'blueprint') {
  g.push(); g.blendMode(ADD); g.noStroke();
  g.fill((P.hue + colorDrift + 40) % 360, 25, 100, Math.min(20, A.treble * P.energy * 20));
  g.rect(0, 0, width, height);
  g.blendMode(BLEND); g.pop();
}

// composite (alpha < 100 = translucent for VJ layering, no main-canvas clear)
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
